head.script:
scwin.isIE = function() {
    var myNav = navigator.userAgent.toLowerCase();
    return (myNav.indexOf('msie') != -1) ? parseInt(myNav.split('msie')[1]) : false;
}
scwin.checkTextArea = function() {
    if (scwin.isIE() == 8) {
        return ((j) => j.length ? j : $('#mf_textarea1'))($('#textarea1')).val() == "setPlaceHolder";
    } else {
        return textarea1.getAttribute("placeholder") == "setPlaceHolder" && ((j) => j.length ? j : $('#mf_textarea1'))($('#textarea1')).val() == "setPlaceHolder";
    }
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    textarea1.setPlaceholder("setPlaceHolder");
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 14-Jun-2018
    //end
}
